-- ============================================================================
-- ONE PIECE / OPTCG -- product-line categorization from set_id prefix (see header comment)
-- ============================================================================
UPDATE cards SET
  series_id = CASE
    WHEN set_id ILIKE 'op%' THEN 'op'
    WHEN set_id ILIKE 'st-%' THEN 'st'
    WHEN set_id ILIKE 'eb%' OR set_id ILIKE 'eb-%' THEN 'eb'
    WHEN set_id ILIKE 'prb%' THEN 'prb'
    WHEN set_id = 'P' THEN 'promo'
    WHEN set_id = 'OTHER' THEN 'other'
    ELSE NULL
  END,
  series_name = CASE
    WHEN set_id ILIKE 'op%' THEN 'Booster Pack'
    WHEN set_id ILIKE 'st-%' THEN 'Starter Deck'
    WHEN set_id ILIKE 'eb%' OR set_id ILIKE 'eb-%' THEN 'Extra Booster'
    WHEN set_id ILIKE 'prb%' THEN 'Premium Booster'
    WHEN set_id = 'P' THEN 'Promotion'
    WHEN set_id = 'OTHER' THEN 'Other Product'
    ELSE NULL
  END
WHERE tcg = 'onepiece' AND source = 'optcg' AND series_id IS NULL
  AND (set_id ILIKE 'op%' OR set_id ILIKE 'st-%' OR set_id ILIKE 'eb%' OR set_id ILIKE 'prb%' OR set_id IN ('P','OTHER'));
